<template>
 <section class="location-picker" :aria-label="label">
  <p class="location-intro">ابحث عن العنوان أو اختر النقطة على الخريطة، ثم أكد المكان. لن يتغير العنوان المكتوب تلقائيًا.</p>
  <div v-if="config.search_enabled" class="location-search" @keydown.enter.stop.prevent="search"><label>ابحث عن شارع أو مكان<input v-model="query" class="setup-input" minlength="3" maxlength="160" placeholder="مثال: الصالحية الجديدة، الشرقية" /></label><button type="button" class="setup-btn" :disabled="searching||query.trim().length<3" @click="search">{{ searching?'جار البحث…':'بحث' }}</button></div>
  <ul v-if="results.length" class="location-results"><li v-for="(result,i) in results" :key="i"><button type="button" @click="selectResult(result)">{{ result.label }}</button></li></ul><p v-if="searched&&!results.length&&!error" role="status">لم نجد نتائج. يمكنك تحديد المكان على الخريطة أو استخدام موقعك.</p>
  <div class="location-tools"><button type="button" class="setup-btn" @click="showMap">{{ expanded?'إعادة عرض الخريطة':'تحديد النقطة على الخريطة' }}</button><button type="button" class="setup-btn" :disabled="locating" @click="locate">{{ locating?'جار تحديد الموقع…':'استخدام موقعي' }}</button></div>
  <div v-if="error" class="setup-error" role="alert">{{ error }}</div>
  <div v-if="expanded" ref="canvas" class="location-map" aria-label="خريطة اختيار العنوان" />
  <p v-if="valid" class="location-status" role="status">{{ modelValue.location_confirmed?'تم تأكيد نقطة العنوان':'النقطة مختارة — راجعها ثم اضغط تأكيد' }}</p>
  <details class="setup-details"><summary>إدخال الإحداثيات يدويًا — عند الحاجة</summary><div class="location-coordinates"><label>خط العرض<input :value="modelValue.latitude" type="number" step="any" min="-90" max="90" class="setup-input" aria-label="خط العرض" @input="setCoordinate('latitude',$event.target.value)" /></label><label>خط الطول<input :value="modelValue.longitude" type="number" step="any" min="-180" max="180" class="setup-input" aria-label="خط الطول" @input="setCoordinate('longitude',$event.target.value)" /></label></div></details>
  <button type="button" class="setup-btn setup-btn-primary location-confirm" :disabled="!valid" @click="confirm">{{ modelValue.location_confirmed?'تم تأكيد نقطة العنوان':'تأكيد نقطة العنوان' }}</button>
  <p v-if="required&&!modelValue.location_confirmed" class="location-intro">تأكيد المكان مطلوب لحساب التوصيل.</p>
  <p v-if="config.search_enabled" class="location-attribution">البحث: <a href="https://www.geoapify.com/" target="_blank" rel="noopener">Powered by Geoapify</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a></p>
 </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import api from '@/api/axios.config'
import '@/modules/guidance/styles/setup.css'
import {safeHtml} from '@/utils/safeHtml'
const props=defineProps({modelValue:{type:Object,required:true},label:{type:String,default:'موقع عنوان التسليم'},required:Boolean,radiusMeters:{type:Number,default:0}})
const emit=defineEmits(['update:modelValue'])
const canvas=ref(),expanded=ref(false),error=ref(''),locating=ref(false),config=ref({search_enabled:false}),query=ref(''),results=ref([]),searching=ref(false),searched=ref(false)
let map,marker,circle,L,disposed=false,searchSequence=0
const valid=computed(()=>[props.modelValue.latitude,props.modelValue.longitude].every(v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v)))&&Math.abs(Number(props.modelValue.latitude))<=90&&Math.abs(Number(props.modelValue.longitude))<=180)
const point=()=>[Number(props.modelValue.latitude),Number(props.modelValue.longitude)]
function update(latitude,longitude){emit('update:modelValue',{...props.modelValue,latitude,longitude,location_confirmed:false})}
function setCoordinate(key,value){update(key==='latitude'?(value===''?null:Number(value)):props.modelValue.latitude,key==='longitude'?(value===''?null:Number(value)):props.modelValue.longitude)}
function confirm(){if(valid.value)emit('update:modelValue',{...props.modelValue,latitude:Number(props.modelValue.latitude),longitude:Number(props.modelValue.longitude),location_confirmed:true})}
function draw(){if(!map||!valid.value)return;const p=point();if(marker)marker.setLatLng(p);else{marker=L.marker(p,{draggable:true,icon:L.divIcon({className:'location-pin',html:'<span></span>',iconSize:[24,24],iconAnchor:[12,12]})}).addTo(map);marker.on('dragend',()=>{const p=marker.getLatLng();update(Number(p.lat.toFixed(7)),Number(p.lng.toFixed(7)))})}circle?.remove();if(props.radiusMeters>0)circle=L.circle(p,{radius:props.radiusMeters,color:'#1749ad',fillOpacity:.08}).addTo(map)}
async function showMap(){expanded.value=true;error.value='';await nextTick();if(map){map.invalidateSize();if(valid.value)map.setView(point(),Math.max(map.getZoom(),15));return}try{const module=await import('leaflet');await import('leaflet/dist/leaflet.css');if(disposed||!canvas.value)return;L=module.default;map=L.map(canvas.value).setView(valid.value?point():[30.0444,31.2357],valid.value?16:7);const attribution=config.value.attribution?'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> · <a href="https://www.geoapify.com/">Powered by Geoapify</a>':safeHtml(import.meta.env.VITE_STORE_MAP_ATTRIBUTION||'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>');L.tileLayer(config.value.tile_url||import.meta.env.VITE_STORE_MAP_TILE_URL||'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution}).on('tileerror',()=>{error.value='تعذر تحميل أجزاء الخريطة. أعد المحاولة أو استخدم موقع الجهاز أو الإحداثيات اليدوية.'}).addTo(map);map.on('click',e=>update(Number(e.latlng.lat.toFixed(7)),Number(e.latlng.lng.toFixed(7))));draw()}catch{error.value='تعذر تشغيل الخريطة. يمكنك استخدام موقع الجهاز أو الإحداثيات اليدوية.'}}
async function search(){if(query.value.trim().length<3)return;const id=++searchSequence;searching.value=true;error.value='';searched.value=false;try{const r=await api.get('/store/public/map-search',{params:{q:query.value.trim()},handleErrorsLocally:true});if(disposed||id!==searchSequence)return;results.value=Array.isArray(r.data?.data)?r.data.data:[];searched.value=true}catch(e){if(!disposed&&id===searchSequence){error.value=e.response?.data?.message||'تعذر البحث. اختر المكان على الخريطة أو استخدم موقعك.';results.value=[]}}finally{if(!disposed&&id===searchSequence)searching.value=false}}
async function selectResult(result){update(result.latitude,result.longitude);results.value=[];await nextTick();await showMap()}
function locate(){error.value='';if(!navigator.geolocation){error.value='هذا الجهاز لا يدعم تحديد الموقع. اختر النقطة يدويًا.';return}locating.value=true;navigator.geolocation.getCurrentPosition(async p=>{if(disposed)return;locating.value=false;update(Number(p.coords.latitude.toFixed(7)),Number(p.coords.longitude.toFixed(7)));await nextTick();await showMap()},()=>{if(disposed)return;locating.value=false;error.value='تعذر الحصول على الموقع أو رُفض الإذن. اختر النقطة على الخريطة أو أدخل إحداثياتها.'},{enableHighAccuracy:true,timeout:12000,maximumAge:0})}
watch(()=>[props.modelValue.latitude,props.modelValue.longitude,props.radiusMeters],draw)
onMounted(async()=>{try{const r=await api.get('/store/public/map-config',{handleErrorsLocally:true});if(!disposed)config.value=r.data?.data||{search_enabled:false}}catch{/* The existing map remains available without a search provider. */}})
onBeforeUnmount(()=>{disposed=true;searchSequence++;map?.remove()})
</script>
<style scoped>
.location-picker{min-width:0;color:rgb(var(--v-theme-on-surface))}.location-intro,.location-attribution{font-size:13px;line-height:1.7;margin:0 0 14px}.location-tools{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.location-map{height:320px;width:100%;border-radius:12px;z-index:0}.location-picker :deep(.leaflet-control-attribution){font-size:11px}.location-search{display:flex;align-items:end;gap:10px}.location-search label{flex:1;min-width:0;display:grid;gap:6px}.location-coordinates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.location-results{list-style:none;padding:0;margin:10px 0}.location-results button{width:100%;text-align:start;padding:12px;min-height:44px;border-bottom:1px solid rgba(var(--v-border-color),.15)}.location-status{font-size:13px;margin-top:10px}.location-confirm{margin:16px 0;width:100%}.location-picker :deep(.location-pin span){display:block;width:24px;height:24px;border-radius:50%;background:rgb(var(--v-theme-primary));border:3px solid rgb(var(--v-theme-surface));box-shadow:0 1px 8px rgba(0,0,0,.25)}@media(max-width:599px){.location-search{flex-wrap:wrap}.location-search label{flex-basis:100%}.location-map{height:300px}}
</style>
